'use strict';
globalThis.LoopCartridge=(()=>{
// Both the blueprint builder and the live worker use this exact seed stream.
function rng(seed) {
  let state = seed >>> 0;
  return () => {
    state = (Math.imul(state, 1664525) + 1013904223) >>> 0;
    return state / 4294967296;
  };
}
function neighbors(i, size) {
  const x = i % size, y = Math.floor(i / size);
  return [[x-1,y],[x+1,y],[x,y-1],[x,y+1]]
    .filter(([a,b]) => a >= 0 && b >= 0 && a < size && b < size)
    .map(([a,b]) => b*size+a);
}
function route(grid, size, from, to) {
  const queue = [from], previous = new Map([[from,-1]]);
  for (let head=0; head < queue.length; head++) {
    const current = queue[head];
    if (current === to) {
      const path = [];
      for (let i = to; i !== from; i=previous.get(i)) path.push(i);
      return path.reverse();
    }
    for (const next of neighbors(current,size)) {
      if (grid[next] && !previous.has(next)) { previous.set(next,current); queue.push(next); }
    }
  }
  return [];
}

// Cartridge ABI. Coordinates are normalized. State and drawing commands are JSON.
function baseStart(L) {
  return {score:0,hits:0,elapsed:0,done:false,won:false,cell:L.from||0,lane:1,mistakes:0};
}
function inCell(index,L) {
  return {x:(index%L.size+0.5)/L.size,y:(Math.floor(index/L.size)+0.5)/L.size};
}
function baseStep(s,e,L) {
  if(s.done) return s;
  if(e.type==='tick') {
    s.elapsed+=e.dt;
    if(s.elapsed>=L.seconds) {s.done=true;return s;}
  }
  const point=L.points[s.hits%L.points.length];
  if(L.family==='trail' && (e.type==='tap' || e.type==='key')) {
    let next=s.cell;
    if(e.type==='tap') next=Math.floor(e.y*L.size)*L.size+Math.floor(e.x*L.size);
    else next+=({ArrowLeft:-1,ArrowRight:1,ArrowUp:-L.size,ArrowDown:L.size}[e.key]||0);
    if(neighbors(s.cell,L.size).includes(next) && L.grid[next]) {
      s.cell=next;s.score++;s.hits++;
      if(next===L.to) s.won=s.done=true;
    }
  } else if(L.family==='drift') {
    if(e.type==='tap') s.lane=Math.min(2,Math.floor(e.x*3));
    if(e.type==='key') s.lane=Math.max(0,Math.min(2,s.lane+({ArrowLeft:-1,ArrowRight:1}[e.key]||0)));
    if(e.type==='tick' && Math.floor(s.elapsed/L.pace)>s.hits+s.mistakes) {
      if(s.lane===point.lane){s.score+=10;s.hits++;}else s.mistakes++;
    }
    if(s.hits>=L.quota) s.won=s.done=true;
  } else if(L.family!=='trail' && e.type==='tap') {
    if(Math.hypot(e.x-point.x,e.y-point.y)<=L.radius) {s.hits++;s.score+=10;}
    else s.mistakes++;
    if(s.hits>=L.quota) s.won=s.done=true;
  }
  return s;
}
function baseDraw(s,L) {
  const commands=[], point=L.points[s.hits%L.points.length];
  if(L.family==='trail') {
    const w=1/L.size;
    for(let i=0;i<L.grid.length;i++) if(!L.grid[i]){
      const p=inCell(i,L); commands.push({kind:'rect',x:p.x-w*.46,y:p.y-w*.46,w:w*.92,h:w*.92,color:'ink'});
    }
    commands.push({kind:'circle',...inCell(L.to,L),r:w*.36,color:'accent'});
    commands.push({kind:'sprite',...inCell(s.cell,L),r:w*.46});
  }else if(L.family==='drift'){
    for(let i=1;i<3;i++) commands.push({kind:'line',x:i/3,y:.02,x2:i/3,y2:.98,color:'soft'});
    const phase=(s.elapsed%L.pace)/L.pace;
    commands.push({kind:'circle',x:(point.lane+.5)/3,y:.09+phase*.74,r:.045,color:'accent'});
    commands.push({kind:'sprite',x:(s.lane+.5)/3,y:.88,r:.07});
  }else{
    for(let i=1;i<4;i++){
      const upcoming=L.points[(s.hits+i)%L.points.length];
      commands.push({kind:'ring',x:upcoming.x,y:upcoming.y,r:.014,color:'soft'});
    }
    commands.push({kind:'ring',x:point.x,y:point.y,r:L.radius*(1.1+.1*Math.sin(s.elapsed*4)),color:'accent'});
    commands.push({kind:'sprite',x:point.x,y:point.y,r:L.radius*.8});
  }
  return commands;
}
function baseWitness(s,L) {
  if(L.family==='trail'){
    const next=route(L.grid,L.size,s.cell,L.to)[0];
    return {type:'tap',...inCell(next,L)};
  }
  const point=L.points[s.hits%L.points.length];
  if(L.family==='drift'){
    if(s.lane!==point.lane) return {type:'tap',x:(point.lane+.5)/3,y:.8};
    return {type:'tick',dt:.1};
  }
  return {type:'tap',x:point.x,y:point.y};
}

function start(L) {
  return {score:0,hits:0,elapsed:0,done:false,won:false,fail:'',prog:0,dev:0,
          dur:L.pace,bs:L.points.map(()=>({lit:false,rem:0,perm:false}))};
}
function step(s,e,L) {
  if(s.done) return s;
  if(e.type==='tap'){
    let best=-1,bd=9;
    s.bs.forEach((b,i)=>{
      if(!b.lit||b.rem<s.dur*.5){
        const d=Math.hypot(e.x-L.points[i].x,e.y-L.points[i].y);
        if(d<=Math.max(L.radius,.05)&&d<bd){bd=d;best=i;}
      }
    });
    if(best>=0){
      const b=s.bs[best];
      if(!b.lit){s.hits++;s.score+=10;}
      b.lit=true;b.rem=s.dur;
      if(L.index===1) b.perm=true;
    }
    return s;
  }
  if(e.type!=='tick') return s;
  s.elapsed+=e.dt;
  s.bs.forEach(b=>{if(b.lit&&!b.perm){b.rem-=e.dt;if(b.rem<=0){b.lit=false;b.rem=0;}}});
  const lit=s.bs.filter(b=>b.lit).length;
  if(lit>0) s.prog=Math.min(1,s.prog+e.dt/(L.seconds*.6));
  else if(!(L.index===1&&s.hits<1)) s.dev+=e.dt;
  if(s.prog>=1&&s.hits>=L.quota){s.won=true;s.done=true;s.score+=50;s.fail='安全入港';return s;}
  const devLimit=Math.min(L.pace*1.2,L.seconds*.5);
  if(s.dev>devLimit){s.done=true;s.fail='偏航失路';}
  else if(s.elapsed>=L.seconds){s.done=true;s.fail='夜未尽，船未归';}
  return s;
}
function draw(s,L) {
  const c=[],port={x:.5,y:.06};
  for(let i=0;i<3;i++){
    const mx=((s.elapsed*.02*(i+1))%1.2)-.1;
    c.push({kind:'rect',x:mx,y:.15+i*.25,w:.5,h:.12,color:'soft'});
  }
  c.push({kind:'line',x:.5,y:.92,x2:port.x,y2:port.y+.04,color:'soft'});
  c.push({kind:'circle',x:port.x,y:port.y,r:.05,color:s.won?'accent':'ink'});
  if(s.won) c.push({kind:'rect',x:.2,y:port.y+.06,w:.6,h:.015,color:'#FFD166'});
  s.bs.forEach((b,i)=>{
    const p=L.points[i];
    if(b.lit){
      const warn=!b.perm&&b.rem<s.dur*.3;
      const col=warn&&Math.sin(s.elapsed*10)>0?'#E4572E':'accent';
      c.push({kind:'circle',x:p.x,y:p.y,r:Math.max(L.radius*.45,.028),color:col});
      c.push({kind:'ring',x:p.x,y:p.y,r:Math.max(L.radius,.05)*(1+.15*Math.sin(s.elapsed*4)),color:col});
      if(!b.perm) c.push({kind:'ring',x:p.x,y:p.y,r:Math.max(L.radius,.05)*1.25,color:warn?'#E4572E':'soft'});
    }else{
      c.push({kind:'ring',x:p.x,y:p.y,r:Math.max(L.radius*.8,.04),color:'ink'});
      if(L.index===1) c.push({kind:'ring',x:p.x,y:p.y,r:Math.max(L.radius,.05)*(1.15+.2*(1+Math.sin(s.elapsed*4))/2),color:'#FFD166'});
    }
  });
  const sx=.5+Math.sin(s.elapsed*2)*.02*(1-s.prog),sy=.92-.86*s.prog;
  c.push({kind:'sprite',x:sx,y:sy,r:.05});
  if(s.dev>0&&Math.sin(s.elapsed*8)>0) c.push({kind:'ring',x:sx,y:sy,r:.07,color:'#E4572E'});
  c.push({kind:'rect',x:.05,y:.03,w:.9*(1-s.elapsed/L.seconds),h:.012,color:'accent'});
  if(s.done) c.push({kind:'text',x:.5,y:.45,text:s.fail,size:9,color:s.won?'accent':'#E4572E'});
  return c;
}
function witness(s,L) {
  if(s.done) return {type:'tick',dt:.1};
  let best=-1,bestKey=Infinity;
  s.bs.forEach((b,i)=>{
    const key=b.lit?b.rem: -1;
    if(key<bestKey){bestKey=key;best=i;}
  });
  if(best>=0&&(!s.bs[best].lit||s.bs[best].rem<s.dur*.5))
    return {type:'tap',x:L.points[best].x,y:L.points[best].y};
  return {type:'tick',dt:.1};
}


